--- The gate decision. Produced only by the backend attestation service (ADR 0004).
---
--- The resource pulls this; it is never pushed to the resource. That leaves no inbound
--- path an attacker could feed (design document 5.2).
--- @return boolean, string|nil
local Verdict_fields = {
    decision = true,
    sessionId = true,
    reasons = true,
    requirements = true,
    remediation = true,
    policyTier = true,
    evaluatedAt = true,
    failOpen = true,
}

function M.validate.Verdict(value, path)
    path = path or 'Verdict'
    if type(value) ~= "table" then
        return fail(path, "expected a table, got " .. type(value))
    end
    local ok, err
    ok, err = check_no_extra_keys(value, path, Verdict_fields)
    if not ok then return false, err end
    if value.decision == nil then return fail(path .. '.decision', "is required") end
    ok, err = check_enum(value.decision, path .. '.decision', 'VerdictDecision')
    if not ok then return false, err end
    if value.sessionId == nil then return fail(path .. '.sessionId', "is required") end
    ok, err = check_string(value.sessionId, path .. '.sessionId', '^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$', 'a UUID', nil, nil)
    if not ok then return false, err end
    if value.reasons == nil then return fail(path .. '.reasons', "is required") end
    ok, err = check_array(value.reasons, path .. '.reasons', 16, function(item, item_path) return check_enum(item, item_path, 'DenyReason') end)
    if not ok then return false, err end
    if value.requirements == nil then return fail(path .. '.requirements', "is required") end
    ok, err = check_array(value.requirements, path .. '.requirements', 32, function(item, item_path) return M.validate.RequirementResult(item, item_path) end)
    if not ok then return false, err end
    if value.remediation ~= nil then
        ok, err = check_string(value.remediation, path .. '.remediation', nil, nil, nil, 500)
        if not ok then return false, err end
    end
    if value.policyTier == nil then return fail(path .. '.policyTier', "is required") end
    ok, err = check_enum(value.policyTier, path .. '.policyTier', 'PolicyTier')
    if not ok then return false, err end
    if value.evaluatedAt == nil then return fail(path .. '.evaluatedAt', "is required") end
    ok, err = check_string(value.evaluatedAt, path .. '.evaluatedAt', '^%d%d%d%d%-%d%d%-%d%dT%d%d:%d%d:%d%d', 'an ISO 8601 timestamp', nil, nil)
    if not ok then return false, err end
    if value.failOpen == nil then return fail(path .. '.failOpen', "is required") end
    ok, err = check_boolean(value.failOpen, path .. '.failOpen')
    if not ok then return false, err end
    return true
end

