--- Step 4: the NUI script pokes the companion on 127.0.0.1.
---
--- This is the only request the localhost endpoint accepts. It carries a nonce and
--- nothing else worth stealing — the backend URL is public and the server name is
--- cosmetic (ADR 0003).
--- @return boolean, string|nil
local LocalAttestCommand_fields = {
    nonce = true,
    backendUrl = true,
    serverName = true,
    protocolVersion = true,
}

function M.validate.LocalAttestCommand(value, path)
    path = path or 'LocalAttestCommand'
    if type(value) ~= "table" then
        return fail(path, "expected a table, got " .. type(value))
    end
    local ok, err
    ok, err = check_no_extra_keys(value, path, LocalAttestCommand_fields)
    if not ok then return false, err end
    if value.nonce == nil then return fail(path .. '.nonce', "is required") end
    ok, err = check_string(value.nonce, path .. '.nonce', '^%x*$', 'hex', 64, 64)
    if not ok then return false, err end
    if value.backendUrl == nil then return fail(path .. '.backendUrl', "is required") end
    ok, err = check_string(value.backendUrl, path .. '.backendUrl', nil, nil, nil, 256)
    if not ok then return false, err end
    if value.serverName ~= nil then
        ok, err = check_string(value.serverName, path .. '.serverName', nil, nil, nil, 128)
        if not ok then return false, err end
    end
    if value.protocolVersion == nil then return fail(path .. '.protocolVersion', "is required") end
    ok, err = check_int(value.protocolVersion, path .. '.protocolVersion', 1, nil)
    if not ok then return false, err end
    return true
end

--- The only thing the localhost endpoint ever returns.
---
--- It is an acknowledgement, not a result. Any local process can reach 127.0.0.1 — CORS
--- protects browsers, not native code — so the endpoint is built to be useless to a
--- caller other than the game client: it can trigger an attestation but can neither read
--- its outcome nor influence it.
--- @return boolean, string|nil
local LocalAttestAck_fields = {
    accepted = true,
    companionVersion = true,
    protocolVersion = true,
}

function M.validate.LocalAttestAck(value, path)
    path = path or 'LocalAttestAck'
    if type(value) ~= "table" then
        return fail(path, "expected a table, got " .. type(value))
    end
    local ok, err
    ok, err = check_no_extra_keys(value, path, LocalAttestAck_fields)
    if not ok then return false, err end
    if value.accepted == nil then return fail(path .. '.accepted', "is required") end
    ok, err = check_boolean(value.accepted, path .. '.accepted')
    if not ok then return false, err end
    if value.companionVersion == nil then return fail(path .. '.companionVersion', "is required") end
    ok, err = check_string(value.companionVersion, path .. '.companionVersion', '^%d+%.%d+%.%d+', 'a semantic version', nil, 32)
    if not ok then return false, err end
    if value.protocolVersion == nil then return fail(path .. '.protocolVersion', "is required") end
    ok, err = check_int(value.protocolVersion, path .. '.protocolVersion', 1, nil)
    if not ok then return false, err end
    return true
end

--- The companion asks the backend whether a player on this machine is connecting.
---
--- ADR 0010. FiveM does not run client resources while a player is held in a connect
--- deferral, so the localhost hop of ADR 0003 cannot carry the nonce at the moment the
--- gate needs it. The companion collects it here instead, and the backend decides which
--- pending session — if any — belongs to this machine.
---
--- The request carries no credential. It cannot: an attacker on this machine holds
--- whatever the companion holds. What limits the answer is the source address, which the
--- caller cannot choose.
--- @return boolean, string|nil
local CompanionPollRequest_fields = {
    companionVersion = true,
    waitSeconds = true,
    protocolVersion = true,
}

function M.validate.CompanionPollRequest(value, path)
    path = path or 'CompanionPollRequest'
    if type(value) ~= "table" then
        return fail(path, "expected a table, got " .. type(value))
    end
    local ok, err
    ok, err = check_no_extra_keys(value, path, CompanionPollRequest_fields)
    if not ok then return false, err end
    if value.companionVersion == nil then return fail(path .. '.companionVersion', "is required") end
    ok, err = check_string(value.companionVersion, path .. '.companionVersion', '^%d+%.%d+%.%d+', 'a semantic version', nil, 32)
    if not ok then return false, err end
    if value.waitSeconds == nil then return fail(path .. '.waitSeconds', "is required") end
    ok, err = check_int(value.waitSeconds, path .. '.waitSeconds', 0, 30)
    if not ok then return false, err end
    if value.protocolVersion == nil then return fail(path .. '.protocolVersion', "is required") end
    ok, err = check_int(value.protocolVersion, path .. '.protocolVersion', 1, nil)
    if not ok then return false, err end
    return true
end

--- A nonce waiting for this machine, or nothing.
---
--- Carries no verdict and no history — only what the companion needs to run one scan and
--- report it. A local process that calls this endpoint learns that somebody at this
--- address is connecting, which it could see on the network anyway.
--- @return boolean, string|nil
local CompanionPollResponse_fields = {
    pending = true,
    nonce = true,
    serverName = true,
    policyTier = true,
    expiresAt = true,
    protocolVersion = true,
}

function M.validate.CompanionPollResponse(value, path)
    path = path or 'CompanionPollResponse'
    if type(value) ~= "table" then
        return fail(path, "expected a table, got " .. type(value))
    end
    local ok, err
    ok, err = check_no_extra_keys(value, path, CompanionPollResponse_fields)
    if not ok then return false, err end
    if value.pending == nil then return fail(path .. '.pending', "is required") end
    ok, err = check_boolean(value.pending, path .. '.pending')
    if not ok then return false, err end
    if value.nonce ~= nil then
        ok, err = check_string(value.nonce, path .. '.nonce', '^%x*$', 'hex', 64, 64)
        if not ok then return false, err end
    end
    if value.serverName ~= nil then
        ok, err = check_string(value.serverName, path .. '.serverName', nil, nil, nil, 128)
        if not ok then return false, err end
    end
    if value.policyTier ~= nil then
        ok, err = check_enum(value.policyTier, path .. '.policyTier', 'PolicyTier')
        if not ok then return false, err end
    end
    if value.expiresAt ~= nil then
        ok, err = check_string(value.expiresAt, path .. '.expiresAt', '^%d%d%d%d%-%d%d%-%d%dT%d%d:%d%d:%d%d', 'an ISO 8601 timestamp', nil, nil)
        if not ok then return false, err end
    end
    if value.protocolVersion == nil then return fail(path .. '.protocolVersion', "is required") end
    ok, err = check_int(value.protocolVersion, path .. '.protocolVersion', 1, nil)
    if not ok then return false, err end
    return true
end

--- The companion asks how the attestation it just filed was judged.
---
--- ADR 0011, which relaxes ADR 0004. The reason and the remediation text are already
