    ok, err = check_no_extra_keys(value, path, ProtocolError_fields)
    if not ok then return false, err end
    if value.code == nil then return fail(path .. '.code', "is required") end
    ok, err = check_string(value.code, path .. '.code', nil, nil, nil, 64)
    if not ok then return false, err end
    if value.message == nil then return fail(path .. '.message', "is required") end
    ok, err = check_string(value.message, path .. '.message', nil, nil, nil, 500)
